const tool=`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Freelancer Capacity Planner | Workload & Project Forecast</title><meta name="description" content="Plan usable client hours, current commitments, new-project fit, project roll-offs, and an eight-week freelance capacity forecast."><meta name="keywords" content="freelancer capacity planner, freelance workload calculator, project capacity calculator, freelancer overbooking calculator"><link rel="canonical" href="https://aicashlabtools.com/${slug}/"><meta property="og:title" content="Freelancer Capacity Planner"><meta property="og:description" content="Determine how much client work you can realistically accept without overbooking."><meta property="og:type" content="website"><meta property="og:url" content="https://aicashlabtools.com/${slug}/"><script type="application/ld+json">${schema}</script><style>${standardHeaderCss}${standardFooterCss}${css}</style></head><body>${standardHeaderHtml}<header class="hero rail"><span class="eyebrow">Freelancer Workload Planning Tool</span><h1>Freelancer Capacity Planner</h1><p>Determine how much client work you can realistically accept without overbooking, burning out, or sacrificing quality.</p></header><section class="quick rail"><strong>Quick Start</strong><ol><li>Set weekly capacity</li><li>Add current projects</li><li>Enter new project</li><li>Review capacity</li><li>Test alternatives</li></ol></section><section class="privacy rail"><span>🔒</span><strong>Private by default:</strong><span>Your inputs stay in your browser and are never uploaded or stored.</span></section><main class="rail"><div class="profiles">${Object.entries(profiles).map(([id,p])=>`<button class="profile${id==='designer'?' active':''}" data-profile="${id}">${p.label}</button>`).join('')}</div><p class="sample-note">These editable sample scenarios are planning examples, not claimed industry benchmarks.</p><div class="app-grid"><div class="stack"><section class="panel"><div class="head"><div><span class="kicker">1 · Available work capacity</span><h2>Build your sustainable week</h2></div><button class="btn" id="reset">Reset</button></div><div class="fields"><div><label>Working hours / week</label><div class="control"><input id="workHours" type="number" min="0" value="40"><span>hrs</span></div></div><div><label>Working days / week</label><div class="control"><input id="workDays" type="number" min="1" max="7" value="5"><span>days</span></div></div><div><label>Non-client / admin hours</label><div class="control"><input id="adminHours" type="number" min="0" value="10"><span>hrs</span></div></div><div><label>Safety / capacity buffer</label><div class="control"><input id="buffer" type="number" min="0" max="100" value="15"><span>%</span></div></div><div class="full"><label>Days off / vacation this month</label><div class="control"><input id="vacation" type="number" min="0" value="1"><span>days</span></div></div><div class="formula"><span>Calculated usable client hours</span><strong id="usableFormula">0 hrs/week</strong><span id="formulaCopy"></span></div></div></section><section class="panel"><div class="head"><div><span class="kicker">2 · Current commitments</span><h2>Active client projects</h2></div><button class="btn" id="addProject">Add Project</button></div><div class="project-list" id="projectList"></div><div class="committed"><span>Committed total</span><strong id="committedTotal">0 hrs/week</strong></div></section><section class="panel"><span class="kicker">3 · Potential new project</span><h2>Test the opportunity</h2><div class="fields"><div class="full"><label>Project / client name</label><div class="control"><input id="newName" value="Mobile App Wireframes"></div></div><div><label>Total estimated hours</label><div class="control"><input id="newHours" type="number" min="0" value="30"><span>hrs</span></div></div><div><label>Deadline</label><div class="control"><input id="deadline" type="number" min="1" value="3"><span>weeks</span></div></div><div class="full"><label>Project value</label><div class="control"><span>$</span><input id="newValue" type="number" min="0" value="3000"></div></div><div class="formula"><span>Required weekly load</span><strong id="requiredWeekly">0 hrs/week</strong><span id="newFitCopy"></span></div></div></section></div><div class="stack"><section class="panel status" id="statusCard"><div class="status-title"><div><span class="kicker">Current capacity result</span><h2 id="statusTitle">Healthy Capacity</h2><p class="copy">Safe capacity reflects the buffer you selected above.</p></div><span class="status-badge" id="statusBadge">Healthy</span></div><div class="metrics"><div class="metric"><span>Usable client hours</span><strong id="usable">0</strong></div><div class="metric"><span>Currently committed</span><strong id="committed">0</strong></div><div class="metric"><span>Remaining safe capacity</span><strong id="remaining">0</strong></div><div class="metric"><span>Capacity utilization</span><strong id="utilization">0%</strong></div></div><div class="meter" id="meter"><i></i></div></section><section class="panel decision"><span class="kicker">Can I take this project?</span><div class="decision-main"><div class="verdict" id="verdict">YES</div><div><h2 id="decisionTitle">This project fits</h2><p class="copy" id="decisionCopy"></p></div></div><div class="alternatives" id="alternatives"></div></section><section class="panel"><span class="kicker">Capacity allocation</span><h2>Where the working week goes</h2><div class="allocation" id="allocation"></div><div class="legend" id="legend"></div></section><section class="panel"><div class="head"><div><span class="kicker">6–8 week forecast</span><h2>Project roll-offs and openings</h2></div></div><div class="forecast-toggle"><button class="btn active" data-forecast="current">Current Projects Only</button><button class="btn" data-forecast="potential">+ Potential New Project</button></div><div class="forecast" id="forecast"></div><div class="opening" id="opening"></div></section></div></div><section class="section block"><span class="kicker">Dynamic recommendations</span><h2>Protect delivery quality and future capacity</h2><div class="recs" id="recommendations"></div></section><details class="section block collapsible"><summary>Revenue Capacity <span class="copy">— secondary analytics</span></summary><p class="copy">Effective revenue per booked hour = committed monthly revenue ÷ 4.33 ÷ booked client hours per week. It is a planning estimate, not realized profit.</p><div class="revenue-grid" id="revenue"></div></details><section class="section block"><div class="head"><div><span class="kicker">Scenario sandbox</span><h2>Current Plan vs Sandbox Scenario</h2><p>Sandbox changes do not alter the main plan until you apply them.</p></div><button class="btn primary" id="applyScenario">Apply Scenario to Main Plan</button></div><div class="sandbox-grid"><div><label>Working hours <span id="sWorkLabel"></span></label><input id="sWork" type="range" min="10" max="80"></div><div><label>Admin hours <span id="sAdminLabel"></span></label><input id="sAdmin" type="range" min="0" max="40"></div><div><label>Buffer <span id="sBufferLabel"></span></label><input id="sBuffer" type="range" min="0" max="40"></div><div><label>New-project deadline <span id="sDeadlineLabel"></span></label><input id="sDeadline" type="range" min="1" max="16"></div></div><div class="compare"><div class="metric"><span>Current plan</span><strong id="currentCompare"></strong></div><div class="metric"><span>Sandbox scenario</span><strong id="sandboxCompare"></strong></div></div></section><section class="section block"><div class="head"><div><span class="kicker">Capacity report</span><h2>Save a useful planning summary</h2></div><button class="btn primary" id="export">Export Capacity Report</button></div><pre id="reportPreview" class="formula"></pre></section><section class="section premium block"><div><span class="kicker">Freelancer Business OS</span><h2>Turn your available capacity into a manageable client system.</h2><p class="copy">Connect proposals, onboarding, scope control, client records, and delivery workflows in one practical workspace.</p></div><a href="https://aicashlabofficial.gumroad.com" target="_blank" rel="noopener">Explore Freelancer Business OS →</a></section><section class="section related block"><div><span class="kicker">Related tools</span><h2>Protect capacity, pricing, and project scope.</h2><p class="copy">Use the next utility that matches your workload decision.</p></div><div class="links"><a href="/hourly-rate-calculator/">Hourly Rate Calculator</a><a href="/value-pricing-vs-hourly-calculator/">Value Pricing vs Hourly Calculator</a><a href="/rush-project-calculator/">Rush Project Calculator</a><a href="/scope-creep-calculator/">Scope Creep Calculator</a><a href="/profit-margin-guard/">Profit Margin Guard</a><a href="/client-lifetime-value-calculator/">Client Lifetime Value Calculator</a></div></section><section class="section block"><span class="kicker">Supporting guides</span><h2>Freelancer Capacity Planning Guides</h2><div class="guides">${guides.map(([s,t,d])=>`<a class="guide" href="/articles/${s}/"><strong>${t}</strong><span>${d}</span></a>`).join('')}</div></section><section class="section block"><h2>Frequently Asked Questions</h2><div class="faq-grid">${faqs.map(([q,a])=>`<details open><summary>${q}</summary><p>${a}</p></details>`).join('')}</div></section></main>${standardFooterHtml}<script>const PROFILES=${JSON.stringify(profiles)};let projects=[],forecastMode='current';const $=id=>document.getElementById(id),n=id=>Math.max(0,Number($(id).value)||0),fmt=x=>(Math.round((Number.isFinite(x)?x:0)*10)/10).toFixed(1).replace('.0',''),money=x=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(Number.isFinite(x)?x:0);function capacity(values){let work=Math.max(0,values.work),days=Math.max(1,values.days),vac=Math.max(0,values.vac),vacWeekly=vac*(work/days)/4.33,gross=Math.max(0,work-vacWeekly),admin=Math.min(gross,Math.max(0,values.admin)),before=Math.max(0,gross-admin),buffer=Math.min(100,Math.max(0,values.buffer)),bufferHours=before*buffer/100,usable=Math.max(0,before-bufferHours),committed=projects.reduce((s,p)=>s+Math.max(0,p.hours),0),remaining=usable-committed,newWeekly=Math.max(0,values.newHours)/Math.max(1,values.deadline),projected=committed+newWeekly,surplus=usable-projected,util=usable>0?committed/usable*100:(committed?999:0),projectUtil=usable>0?projected/usable*100:(projected?999:0),fits=surplus>=-0.001;return{...values,vacWeekly,gross,admin,before,bufferHours,usable,committed,remaining,newWeekly,projected,surplus,util,projectUtil,fits}}function mainValues(){return{work:n('workHours'),days:Math.max(1,n('workDays')),admin:n('adminHours'),buffer:Math.min(100,n('buffer')),vac:n('vacation'),newHours:n('newHours'),deadline:Math.max(1,n('deadline'))}}function statusFor(load,usable){let d=usable-load;if(load>usable+.01)return'over';if(d<=Math.max(1,usable*.1))return'near';return'healthy'}function renderProjects(){ $('projectList').innerHTML=projects.map((p,i)=>'<div class="project" data-index="'+i+'"><div class="project-name"><label>Project / client</label><div class="control"><input data-field="name" value="'+escapeHtml(p.name)+'"></div></div><div><label>Hours / week</label><div class="control"><input data-field="hours" type="number" min="0" value="'+p.hours+'"></div></div><div><label>Weeks left</label><div class="control"><input data-field="weeks" type="number" min="0" value="'+p.weeks+'"></div></div><div><label>Monthly revenue</label><div class="control"><input data-field="revenue" type="number" min="0" value="'+p.revenue+'"></div></div><button class="delete" data-delete="'+i+'">Delete</button></div>').join('')||'<p class="copy">No current projects. Add one when you are ready.</p>';document.querySelectorAll('.project input').forEach(x=>x.oninput=e=>{let row=e.target.closest('.project'),i=Number(row.dataset.index),f=e.target.dataset.field;projects[i][f]=f==='name'?e.target.value:Math.max(0,Number(e.target.value)||0);render()});document.querySelectorAll('[data-delete]').forEach(x=>x.onclick=()=>{projects.splice(Number(x.dataset.delete),1);renderProjects();render()})}function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function forecast(r,include){let cards=[],prev=r.committed,opening=null;for(let w=1;w<=8;w++){let active=projects.filter(p=>p.weeks>=w),comm=active.reduce((s,p)=>s+p.hours,0),newH=include&&w<=r.deadline?r.newWeekly:0,total=comm+newH,st=statusFor(total,r.usable),roll=projects.filter(p=>p.weeks===w).map(p=>p.name);if(opening===null&&w>1&&comm<prev-.01)opening={week:w,freed:r.usable-comm,names:projects.filter(p=>p.weeks===w-1).map(p=>p.name)};cards.push({w,comm,newH,total,st,active:active.map(p=>p.name),roll});prev=comm}return{cards,opening}}function render(){let r=capacity(mainValues()),st=statusFor(r.committed,r.usable),projectSt=statusFor(r.projected,r.usable);$('usableFormula').textContent=fmt(r.usable)+' hrs/week';$('formulaCopy').textContent=fmt(r.gross)+' gross - '+fmt(r.admin)+' admin - '+fmt(r.bufferHours)+' buffer = '+fmt(r.usable)+' usable client hrs/week. Vacation reduces gross capacity by '+fmt(r.vacWeekly)+' hrs/week.';$('committedTotal').textContent=fmt(r.committed)+' hrs/week';$('requiredWeekly').textContent=fmt(r.newWeekly)+' hrs/week';$('newFitCopy').textContent=r.fits?'Fits with '+fmt(r.surplus)+' hrs/week remaining.':'Exceeds safe capacity by '+fmt(Math.abs(r.surplus))+' hrs/week.';$('usable').textContent=fmt(r.usable);$('committed').textContent=fmt(r.committed);$('remaining').textContent=fmt(r.remaining);$('utilization').textContent=Math.round(r.util)+'%';let title=st==='healthy'?'Healthy Capacity':st==='near'?'Near Capacity':'Over Capacity';$('statusTitle').textContent=title;$('statusBadge').textContent=title.replace(' Capacity','');$('statusCard').className='panel status '+(st==='near'?'near':st==='over'?'over':'');$('meter').className='meter '+(st==='near'?'near':st==='over'?'over':'');$('meter').querySelector('i').style.width=Math.min(100,Math.max(0,r.util))+'%';let exact=Math.abs(r.surplus)<.05,verdict=r.fits?(exact?'BORDERLINE':'YES'):'NO';$('verdict').textContent=verdict;$('verdict').className='verdict '+(r.fits?(exact?'edge':''):'no');$('decisionTitle').textContent=r.fits?(exact?'This project exactly fills safe capacity':'This project fits your safe capacity'):'This project exceeds safe capacity';$('decisionCopy').textContent=r.fits?'The project needs '+fmt(r.newWeekly)+' hrs/week and leaves '+fmt(Math.max(0,r.surplus))+' hrs/week of safe capacity.':'Accepting this project now exceeds safe capacity by '+fmt(Math.abs(r.surplus))+' hrs/week.';let available=Math.max(0,r.remaining),extend=available>0?Math.max(r.deadline,Math.ceil(r.newHours/available)):null,maxScope=Math.max(0,available*r.deadline),fc=forecast(r,true),delay=0;for(let c of fc.cards){if(r.usable-c.comm>=r.newWeekly-.001){delay=c.w-1;break}}let alts=[];if(!r.fits){alts.push(['A · Extend Completion Deadline',extend?extend+' weeks':'Wait for capacity','Minimum whole-week deadline based on current remaining capacity.']);alts.push(['B · Reduce Project Scope',fmt(maxScope)+' total hours','Approximate scope that fits the current deadline.']);alts.push(['C · Delay Project Start Date',delay?'Start in Week '+(delay+1):'No opening within 8 weeks','First forecast week where all active commitments leave enough room.']);alts.push(['D · Squeeze Safety Buffer','Risk scenario only','Reducing the buffer may make the math fit, but removes protection for revisions and delays.'])}$('alternatives').innerHTML=alts.map((a,i)=>'<article class="alternative '+(i===3?'risk':'')+'"><span>'+a[0]+'</span><strong>'+a[1]+'</strong><p>'+a[2]+'</p></article>').join('');let totalWeek=Math.max(1,r.work),segments=[['Active client work',r.committed,'#60a5fa'],['Potential project',r.newWeekly,'#fb923c'],['Non-client / admin',r.admin,'#c084fc'],['Safety buffer',r.bufferHours,'#fb7185'],['Remaining / free',Math.max(0,r.work-r.committed-r.newWeekly-r.admin-r.bufferHours-r.vacWeekly),'#34d399']];$('allocation').innerHTML=segments.map(x=>'<i title="'+x[0]+': '+fmt(x[1])+' hrs" style="width:'+Math.max(0,x[1]/totalWeek*100)+'%;background:'+x[2]+'"></i>').join('');$('legend').innerHTML=segments.map(x=>'<span><b style="background:'+x[2]+'"></b>'+x[0]+' '+fmt(x[1])+'h</span>').join('');let view=forecast(r,forecastMode==='potential');$('forecast').innerHTML=view.cards.map(c=>'<article class="week '+c.st+'"><h3><span>Week '+c.w+'</span><span>'+c.st.replace('healthy','Healthy').replace('near','Tight').replace('over','Over')+'</span></h3><p><strong>'+fmt(c.total)+'h booked</strong> / '+fmt(r.usable)+'h safe</p><p>'+c.active.length?c.active.join(', '):'No active projects'+'</p>'+(c.newH?'<p class="roll">Proposed: '+fmt(c.newH)+'h</p>':'')+(c.roll.length?'<p class="roll">Roll-off after week: '+c.roll.join(', ')+'</p>':'')+'</article>').join('');$('opening').textContent=view.opening?'Next major capacity opening: Week '+view.opening.week+' after '+(view.opening.names.join(', ')||'project commitments')+' roll off, leaving '+fmt(view.opening.freed)+' hrs/week available.':'No major current-project opening appears inside this 8-week forecast.';let rec=[];if(st==='over')rec.push(['Protect Existing Delivery','Current commitments exceed safe capacity. Renegotiate timelines or reduce active scope before adding work.']);else if(st==='near')rec.push(['Protect the Remaining Margin','You are approaching your selected capacity limit. Avoid recurring additions without changing scope or timing.']);else rec.push(['Healthy Capacity','You retain '+fmt(Math.max(0,r.remaining))+' safe client hours per week before the proposed project.']);if(!r.fits)rec.push(['Use the Calculated Alternative',delay?'Delay the start to Week '+(delay+1)+' or extend the deadline.':'Extend the deadline or reduce project scope.']);if(r.util>=80)rec.push(['Test Pricing Before Adding Hours','You are approaching your selected capacity limit. If inquiries remain strong, consider testing higher rates on future projects.']);if(r.admin/r.work>.25)rec.push(['Review Admin Load','Admin work uses '+Math.round(r.admin/Math.max(1,r.work)*100)+'% of scheduled hours. Streamline recurring operations where practical.']);$('recommendations').innerHTML=rec.slice(0,4).map(x=>'<article class="rec"><strong>'+x[0]+'</strong><p>'+x[1]+'</p></article>').join('');let monthly=projects.reduce((s,p)=>s+p.revenue,0),weekly=monthly/4.33,eff=r.committed>0?weekly/r.committed:0,potential=n('newValue')/r.deadline*4.33;$('revenue').innerHTML=[['Committed monthly revenue',money(monthly)],['Estimated revenue / booked hour',r.committed?money(eff)+'/hr':'Not available'],['Potential monthly project value',money(potential)],['Unfilled safe hours',fmt(Math.max(0,r.remaining))+' hrs/week']].map(x=>'<div class="metric"><span>'+x[0]+'</span><strong>'+x[1]+'</strong></div>').join('');$('reportPreview').textContent=report(r);renderSandbox(r)}function report(r){return'FREELANCER CAPACITY PLAN\nUsable client capacity: '+fmt(r.usable)+' hrs/week\nCurrent commitments: '+fmt(r.committed)+' hrs/week\nRemaining safe capacity: '+fmt(r.remaining)+' hrs/week\nProposed project: '+($('newName').value||'New Project')+'\nRequired project load: '+fmt(r.newWeekly)+' hrs/week\nDecision: '+(r.fits?'FITS SAFE CAPACITY':'EXCEEDS SAFE CAPACITY')+'\nCapacity surplus / deficit: '+fmt(r.surplus)+' hrs/week\nVacation adjustment: '+fmt(r.vacWeekly)+' hrs/week\nSafety buffer: '+fmt(r.bufferHours)+' hrs/week'}function renderSandbox(base){let sv=capacity({work:n('sWork'),days:base.days,admin:n('sAdmin'),buffer:n('sBuffer'),vac:base.vac,newHours:base.newHours,deadline:Math.max(1,n('sDeadline'))});$('sWorkLabel').textContent=n('sWork')+'h';$('sAdminLabel').textContent=n('sAdmin')+'h';$('sBufferLabel').textContent=n('sBuffer')+'%';$('sDeadlineLabel').textContent=n('sDeadline')+' wks';$('currentCompare').textContent=fmt(base.usable)+' safe hrs · '+(base.fits?'Fits':'Over');$('sandboxCompare').textContent=fmt(sv.usable)+' safe hrs · '+(sv.fits?'Fits':'Over')}function loadProfile(id){let p=PROFILES[id],s=p.settings;['workHours','workDays','adminHours','buffer','vacation'].forEach((x,i)=>$(x).value=s[i]);projects=p.projects.map((x,i)=>({id:Date.now()+i,name:x[0],hours:x[1],weeks:x[2],revenue:x[3]}));['newName','newHours','deadline','newValue'].forEach((x,i)=>$(x).value=p.next[i]);document.querySelectorAll('.profile').forEach(x=>x.classList.toggle('active',x.dataset.profile===id));renderProjects();syncSandbox();render()}function syncSandbox(){ $('sWork').value=n('workHours');$('sAdmin').value=n('adminHours');$('sBuffer').value=n('buffer');$('sDeadline').value=n('deadline')}['workHours','workDays','adminHours','buffer','vacation','newName','newHours','deadline','newValue'].forEach(id=>$(id).addEventListener('input',()=>{render()}));document.querySelectorAll('.profile').forEach(x=>x.onclick=()=>loadProfile(x.dataset.profile));document.querySelectorAll('[data-forecast]').forEach(x=>x.onclick=()=>{forecastMode=x.dataset.forecast;document.querySelectorAll('[data-forecast]').forEach(b=>b.classList.toggle('active',b===x));render()});['sWork','sAdmin','sBuffer','sDeadline'].forEach(id=>$(id).oninput=()=>renderSandbox(capacity(mainValues())));$('applyScenario').onclick=()=>{$('workHours').value=n('sWork');$('adminHours').value=n('sAdmin');$('buffer').value=n('sBuffer');$('deadline').value=n('sDeadline');render()};$('addProject').onclick=()=>{projects.push({id:Date.now(),name:'New Client Project',hours:5,weeks:4,revenue:0});renderProjects();render()};$('reset').onclick=()=>loadProfile('designer');$('export').onclick=()=>{let blob=new Blob([$('reportPreview').textContent],{type:'text/plain'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='freelancer-capacity-plan.txt';a.click();URL.revokeObjectURL(a.href)};loadProfile('designer');</script></body></html>`;

const articleCss=`${standardHeaderCss}${standardFooterCss}*{box-sizing:border-box}body{margin:0;background:#0b0f17;color:#cbd5e1;font-family:Inter,system-ui,sans-serif;line-height:1.72}.acl-standard-header{position:relative!important}.shell{max-width:960px;margin:auto;padding:44px 20px}.hero,.article{border:1px solid #273244;border-radius:16px;background:#131926;padding:clamp(24px,5vw,46px)}.hero{border-color:#f59e0b55;background:linear-gradient(135deg,#f59e0b15,#111827);margin-bottom:22px}.k{color:#f59e0b;font-size:11px;font-weight:900;letter-spacing:.13em;text-transform:uppercase}h1{margin:10px 0;font-size:clamp(2rem,5vw,3.5rem);line-height:1.08;color:#fff}h2{margin:28px 0 8px;color:#fff;line-height:1.25}.hero p,.article p,.article li{color:#b7c2d1}.cta{margin-top:30px;border:1px solid #f59e0b55;border-radius:12px;background:#0d1420;padding:20px}.cta a{display:inline-block;margin-top:8px;border-radius:8px;background:#f59e0b;padding:10px 14px;color:#111827;text-decoration:none;font-weight:900}`;
function articleBody(t){if(t.includes('Calculate'))return'<h2>Start with scheduled hours</h2><p>Use the hours you actually intend to work, then convert monthly time off into a weekly adjustment.</p><h2>Deduct recurring non-client work</h2><p>Administration, sales, invoicing, and project management consume real capacity even when clients never see them itemized.</p><h2>Apply one consistent buffer</h2><p>This planner applies the selected buffer to capacity after vacation and administration. That method is used consistently throughout the result and forecast.</p><h2>Compare commitments with usable hours</h2><p>Remaining safe capacity equals usable client hours minus current weekly commitments.</p>';if(t.includes('Overbooking'))return'<h2>Measure before accepting</h2><p>Turn every project into a weekly load and compare it with remaining safe capacity.</p><h2>Use timing as a pricing and scope tool</h2><p>When work does not fit, extend the deadline, reduce scope, or delay the start until enough projects roll off.</p><h2>Protect the buffer</h2><p>Squeezing the safety buffer may make a proposal fit on paper while transferring all risk into delivery.</p>';if(t.includes('Admin'))return'<h2>Convert monthly days off fairly</h2><p>Estimate daily hours and divide monthly time off across 4.33 weeks. One eight-hour day off reduces weekly capacity by about 1.85 hours.</p><h2>Track non-client work separately</h2><p>Use a realistic weekly average for invoicing, sales, calls, and business operations.</p><h2>Avoid double counting</h2><p>Do not also hide recurring administration inside the safety buffer. The buffer is for uncertainty, while admin time is planned work.</p>';if(t.includes('Forecast'))return'<h2>Use consistent week boundaries</h2><p>A project with two weeks left remains active in Weeks 1 and 2 and releases capacity in Week 3.</p><h2>Compare both scenarios</h2><p>View current commitments alone, then add the proposed project to see whether it creates a tight or over-capacity week.</p><h2>Plan around roll-offs</h2><p>Delay-start logic should consider all projects active in each future week, not only the first contract ending.</p>';return'<h2>Capacity is not the same as working time</h2><p>Usable client capacity begins after vacation, administration, and the safety buffer are deducted.</p><h2>Model project load weekly</h2><p>Divide estimated project hours by the available deadline, then compare that load with existing commitments.</p><h2>Use the forecast to negotiate</h2><p>Capacity planning supports better deadline, scope, and pricing conversations before delivery risk becomes urgent.</p>'}
function articlePage([s,t,d]){let sc=JSON.stringify({'@context':'https://schema.org','@type':'Article',headline:t,description:d,url:`https://aicashlabtools.com/articles/${s}/`});return`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${t} | AI Cash Lab</title><meta name="description" content="${d}"><link rel="canonical" href="https://aicashlabtools.com/articles/${s}/"><script type="application/ld+json">${sc}</script><style>${articleCss}</style></head><body>${standardHeaderHtml}<main class="shell"><header class="hero"><span class="k">Freelancer Capacity Guide</span><h1>${t}</h1><p>${d}</p></header><article class="article">${articleBody(t)}<div class="cta"><strong>Test your own workload.</strong><p>Use the free planner to model safe hours, project roll-offs, alternatives, and an eight-week forecast.</p><a href="/${slug}/">Open Freelancer Capacity Planner →</a></div></article></main>${standardFooterHtml}</body></html>`}
